     }

     /**
@@ -48,9 +48,19 @@ class FeatureFlagService
             LUA;

         $this->redis->eval($script, [
-            "flags:{$tenant}:uses",
-            "flags:{$tenant}:version",
+            $this->usesKey($tenant),
+            $this->versionKey($tenant),
             $version,
         ], 2);
     }
+
+    private function usesKey(string $tenant): string
+    {
+        return "flags:{{$tenant}}:uses";
+    }
+
+    private function versionKey(string $tenant): string
+    {
+        return "flags:{{$tenant}}:version";
+    }
